#[cfg(test)]
include!("native_floor_build.rs");

// Generated by the same scanner as the slow reference path. No on-disk cache
// survives compiler rebuilds; Cargo tracks the scanner and codegen dependency.
fn load_runtime_index() -> RuntimeIndex {
    include!(concat!(env!("OUT_DIR"), "/native_floor_index.rs"))
}

#[cfg(test)]
mod generated_index_tests {
    use super::*;

    #[test]
    fn generated_index_matches_runtime_scan() {
        let generated = runtime_index();
        let scanned = build_runtime_index();
        assert_eq!(generated.defined, scanned.defined);
        assert_eq!(generated.trait_methods, scanned.trait_methods);
        assert_eq!(generated.fns, scanned.fns);
        assert_eq!(generated.items.len(), scanned.items.len());
        for (name, item) in &scanned.items {
            let loaded = &generated.items[name];
            assert_eq!(loaded.text, item.text, "{name}");
            assert_eq!(is_fs_host_text_in(generated, loaded.text), is_fs_host_text_in(&scanned, item.text), "fs provenance: {name}");
        }
    }
}
